const request = $input.first().json;
const body = request.body && typeof request.body === 'object' ? request.body : request;
const now = Date.now();
const question = typeof body.question === 'string' ? body.question.trim() : '';
const sessionId = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
const cleanOptional = (value) => typeof value === 'string' ? value.trim().slice(0, 80) : '';
const reject = (status, code, error) => [{ json: { valid: false, status, code, error } }];

if (question.length < 2 || question.length > 200) {
  return reject(400, 'invalid_question', 'La question doit contenir entre 2 et 200 caractères.');
}
if (!/^[A-Za-z0-9_-]{8,64}$/.test(sessionId)) {
  return reject(400, 'invalid_session', 'Identifiant de session invalide.');
}

const state = $getWorkflowStaticData('global');
state.questionRateLimits = state.questionRateLimits || {};
const hourAgo = now - 60 * 60 * 1000;
const minuteAgo = now - 60 * 1000;
const recent = (state.questionRateLimits[sessionId] || []).filter((timestamp) => timestamp > hourAgo);
if (recent.filter((timestamp) => timestamp > minuteAgo).length >= 6 || recent.length >= 30) {
  state.questionRateLimits[sessionId] = recent;
  return reject(429, 'rate_limited', 'Trop de demandes pour cette session. Réessayez plus tard.');
}
recent.push(now);
state.questionRateLimits[sessionId] = recent;
for (const [key, timestamps] of Object.entries(state.questionRateLimits)) {
  const active = timestamps.filter((timestamp) => timestamp > hourAgo);
  if (active.length) state.questionRateLimits[key] = active;
  else delete state.questionRateLimits[key];
}

return [{ json: {
  valid: true,
  status: 200,
  question,
  sessionId,
  source: cleanOptional(body.source),
  company: cleanOptional(body.company)
} }];
